@Component("agent-handler")
@ProcessingGroup("agent-processing-group")
public class AgentEventHandler {
	
	// core constructor
	AgentEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateAgentEvent
     */
    @EventHandler
    public void handle( CreateAgentEvent event) {
        entityManager.persist(new Agent(event.getAgentId(), event.getFirstName(), event.getLastName(), event.getLicenseId(), event.getDistributor(), event.getPolicies(), event.getCustomers(), event.getStatus()));
    }

    /*
     * @param	event UpdateAgentEvent
     */
    @EventHandler
    public Agent handle( UpdateAgentEvent event) {
    	entityManager.merge(new Agent(event.getAgentId(), event.getFirstName(), event.getLastName(), event.getLicenseId(), event.getDistributor(), event.getPolicies(), event.getCustomers(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteAgentEvent
     */
    @EventHandler
    public void on( DeleteAgentEvent event) {
    	Agent entity = new Agent();
   
    	// ------------------------------------------
    	// apply the AgentId
    	// ------------------------------------------
    	entity.setAgentId( event.getAgentId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final AgentRepository agentEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(AgentEventHandler.class.getName());

}
